package com.sumirelabs.sum1rem0d.game;
import com.google.gson.*;
import com.sumirelabs.sum1rem0d.Sum1reM0d;
import com.sumirelabs.sum1rem0d.network.ServerConfigHandler;
import java.util.*;
import java.nio.file.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.network.Connection;
import net.minecraft.network.protocol.PacketFlow;
import net.minecraft.server.level.ClientInformation;
import net.minecraft.server.network.CommonListenerCookie;
import com.mojang.authlib.GameProfile;
import net.minecraft.world.item.*;
import net.minecraft.world.level.storage.*;
import net.minecraft.util.ProblemReporter;

/** Disposable local-client fixture; restores native player NBT and persistent mod state on every exit. */
public final class RemainingLiveVerification {
 private static ServerPlayer actor,walletNear,walletFar;private static JsonObject config,world;private static net.minecraft.nbt.CompoundTag player;private static long started,finishAt;private static boolean finished,restored;private static net.minecraft.world.level.GameType mode;
 private RemainingLiveVerification(){}
 public static boolean temporary(ServerPlayer p){return Boolean.getBoolean("sum1rem0d.remainingVerify") && p==actor && !restored;}
 public static void tick(MinecraftServer server){
  if(!Boolean.getBoolean("sum1rem0d.remainingVerify") || finished)return;
  try{
   var stopSignal=server.getWorldPath(LevelResource.ROOT).resolve("sum1rem0d-verification-stop");
   if(Files.deleteIfExists(stopSignal)){finish(server,false,"Stopped by local verification runner");return;}
   if(actor==null){if(server.getPlayerList().getPlayers().isEmpty())return;ServerVerification.require(server.getPlayerList().getPlayers().size()==1,"Only one local fixture client");actor=server.getPlayerList().getPlayers().getFirst();ServerVerification.require(actor.getGameProfile().name().equals("Developer"),"Local developer account only");started=System.nanoTime();config=Sum1reM0d.config().snapshot();world=WorldState.get(server).checkpoint();var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,actor.registryAccess());actor.saveWithoutId(out);player=out.buildResult();mode=actor.gameMode.getGameModeForPlayer();
    var draft=config.deepCopy();var fs=draft.getAsJsonObject("features");for(var row:fs.entrySet())row.getValue().getAsJsonObject().addProperty("enabled",false);for(String id:List.of("economy","player_trading","sumzon","ad_premium","sumzon_prime","mixed_concrete","mixed_wool","mixed_bed","emerald_equipment","redstone_equipment","lapis_equipment","tamed_book","scribbling_book"))fs.getAsJsonObject(id).addProperty("enabled",true);fs.getAsJsonObject("sumzon").addProperty("delivery_hours",0);fs.getAsJsonObject("sumzon").addProperty("allow_creative",true);fs.getAsJsonObject("sumzon").addProperty("prices","minecraft:diamond=500");fs.getAsJsonObject("sumzon").addProperty("shipping",25);fs.getAsJsonObject("economy").addProperty("allow_creative_wallet",true);fs.getAsJsonObject("player_trading").addProperty("allow_creative",true);fs.getAsJsonObject("scribbling_book").addProperty("interval",20);fs.getAsJsonObject("scribbling_book").addProperty("speed_multiplier",4);Sum1reM0d.config().update(draft,Sum1reM0d.config().revision());var d=WorldState.get(server).player(actor);d.walletInitialized=true;d.coins=100000;d.services=new JsonObject();actor.getInventory().clearContent();actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);actor.setNoGravity(true);actor.connection.teleport(0.5,245,0.5,0,0);MixedColorFixture.setup(actor);walletNear=fixturePlayer(server,actor,"SumireNear",3);walletFar=fixturePlayer(server,actor,"SumireFar",30);actor.inventoryMenu.broadcastFullState();ServerConfigHandler.send(actor,"");Gameplay.sendState(actor);
   }
   if(finishAt>0 && server.overworld().getGameTime()>=finishAt){finish(server,true,"");return;}
   if(System.nanoTime()-started>240_000_000_000L)finish(server,false,"Client timeout");
  }catch(Throwable e){Sum1reM0d.LOGGER.error("Remaining live fixture failed",e);finish(server,false,e.toString());}
 }
 public static void command(ServerPlayer p,String phase){if(!temporary(p))throw new IllegalArgumentException("Verification unavailable");switch(phase){case "normal_book"->{if(p.getMainHandItem().is(Items.DIAMOND))p.getInventory().setItem(8,p.getMainHandItem().copy());p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.WRITABLE_BOOK));}case "tamed_book"->p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(ExtraContent.item("tamed_book")));case "creative_on"->{p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);ServerConfigHandler.send(p,"");Gameplay.sendState(p);}case "wallet_seed"->{p.getInventory().setItem(10,new ItemStack(ModContent.coin(),5));p.inventoryMenu.broadcastFullState();Gameplay.sendState(p);}case "wallet_invite_check"->{var near=Economy.state(walletNear);var far=Economy.state(walletFar);ServerVerification.require(near.has("inviteName")&&near.get("inviteName").getAsString().equals(p.getGameProfile().name()),"Wallet widget must send the invite to its selected nearby player");ServerVerification.require(!far.has("inviteName"),"Wallet nearby selection must not target a player outside the configured range");}case "finish"->{ServerVerification.require(ShopServices.active(p,"ad")&&ShopServices.active(p,"prime"),"Both paid contracts reached server");ServerVerification.require(p.getInventory().countItem(Items.DIAMOND)==3,"Survival and creative Sumzon checkouts delivered exactly three diamonds");finishAt=p.level().getGameTime()+20;}default->throw new IllegalArgumentException(phase);}p.inventoryMenu.broadcastFullState();}
 public static void leaving(ServerPlayer p){if(temporary(p)&&!finished)finish(p.level().getServer(),false,"Client left before completion");}
 public static void stopping(MinecraftServer server){if(Boolean.getBoolean("sum1rem0d.remainingVerify")&&!finished)finish(server,false,"Stopped before completion");}
 private static ServerPlayer fixturePlayer(MinecraftServer server,ServerPlayer anchor,String name,double distance){var profile=new GameProfile(java.util.UUID.randomUUID(),name);var connection=new Connection(PacketFlow.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(connection);var fixture=new ServerPlayer(server,anchor.level(),profile,ClientInformation.createDefault());server.getPlayerList().placeNewPlayer(connection,fixture,CommonListenerCookie.createInitial(profile,false));fixture.setPos(anchor.getX()+distance,anchor.getY(),anchor.getZ());fixture.setNoGravity(true);return fixture;}
 private static void removeFixturePlayers(MinecraftServer server)throws java.io.IOException{java.io.IOException failure=null;for(var fixture:new ServerPlayer[]{walletNear,walletFar}){if(fixture==null)continue;try{server.getPlayerList().remove(fixture);fixture.discard();String uuid=fixture.getUUID().toString();var playerData=server.getWorldPath(LevelResource.ROOT).resolve("playerdata");Files.deleteIfExists(playerData.resolve(uuid+".dat"));Files.deleteIfExists(playerData.resolve(uuid+".dat_old"));Files.deleteIfExists(server.getWorldPath(LevelResource.ROOT).resolve("stats").resolve(uuid+".json"));Files.deleteIfExists(server.getWorldPath(LevelResource.ROOT).resolve("advancements").resolve(uuid+".json"));}catch(Exception e){if(failure==null)failure=new java.io.IOException("Could not remove Wallet fixture "+fixture.getUUID(),e);else failure.addSuppressed(e);}}walletNear=null;walletFar=null;if(failure!=null)throw failure;}
 private static void finish(MinecraftServer server,boolean success,String failure){if(finished)return;finished=true;try{if(config!=null){actor.closeContainer();removeFixturePlayers(server);MixedColorFixture.restore(actor);actor.load(TagValueInput.create(ProblemReporter.DISCARDING,actor.registryAccess(),player));actor.setGameMode(mode);actor.setNoGravity(false);WorldState.get(server).restore(world);WorldState.get(server).saveStrict();Sum1reM0d.config().update(config,Sum1reM0d.config().revision());actor.inventoryMenu.broadcastFullState();restored=true;server.getPlayerList().saveAll();}}catch(Exception e){success=false;failure+="; restore "+e;}var report=new JsonObject();report.addProperty("success",success);report.addProperty("failure",failure);report.add("passed",new Gson().toJsonTree(List.of("real shop checkout and exact inventory delivery","real premium and Prime contracts","real wallet nearby selection and creative actions","fixture player NBT, config and world-state restoration")));try{Files.writeString(server.getWorldPath(LevelResource.ROOT).resolve("sum1rem0d-remaining-live.json"),new GsonBuilder().setPrettyPrinting().create().toJson(report));}catch(Exception e){throw new IllegalStateException(e);}server.halt(false);}
}
